report = replace_once(
    report,
    "FarolDiagnosticSummary0164.withSummary",
    "FarolDiagnosticSummary0165.withSummary",
    "integração do resumo por tentativas",
)
report_file.write_text(report, encoding="utf-8")
print("0.1.165: resumo diagnóstico reconstruído por tentativas independentes")
